<?php

declare(strict_types=1);

/**
 * Regenerates the emoji shortcode tables: `php bin/generate-emoji-shortcodes.php`.
 *
 * Run by hand when the vocabulary should change, never automatically - it is a
 * deliberate act, and the generated files are checked in so no install step
 * depends on reaching the network.
 *
 * The source is emojibase's GitHub shortcode set. There is no authoritative
 * list: Unicode and CLDR define emoji names and keywords, not colon codes, and
 * the three sets emojibase publishes disagree with each other about the same
 * character. GitHub's is the one people have actually typed for a decade, and
 * it is the smallest, which matters because it ships to every page.
 *
 * Two files come out of one source, so the server and the browser cannot
 * disagree about what a shortcode means:
 *
 *   src/classes/EmojiShortcodeMap.php
 *   scripts/EmojiShortcodeMap.js
 *
 * Both hold only data. The substitution itself lives in EmojiShortcode.php and
 * EmojiRenderer.js, which are written by hand and never touched by this.
 */

if (PHP_SAPI !== 'cli') {
    exit(1);
}

const SOURCE_URL = 'https://cdn.jsdelivr.net/npm/emojibase-data@latest/en/shortcodes/github.json';

$project_root = dirname(__DIR__);

fwrite(STDOUT, 'Fetching ' . SOURCE_URL . "\n");

$raw = @file_get_contents(SOURCE_URL);

if ($raw === false) {
    fwrite(STDERR, "Could not fetch the shortcode set.\n");
    exit(1);
}

$source = json_decode($raw, true);

if (!is_array($source)) {
    fwrite(STDERR, "The shortcode set did not parse as JSON.\n");
    exit(1);
}

$map = [];
$rejected = [];

foreach ($source as $hexcode => $shortcodes) {
    // A hexcode is one or more codepoints joined by hyphens: 1F1E6-1F1EA is a
    // flag built from two regional indicators.
    $emoji = '';
    $usable = true;

    foreach (explode('-', (string) $hexcode) as $codepoint) {
        $character = mb_chr((int) hexdec($codepoint), 'UTF-8');

        if ($character === false) {
            $usable = false;
            break;
        }

        $emoji .= $character;
    }

    if (!$usable) {
        continue;
    }

    foreach ((array) $shortcodes as $shortcode) {
        $shortcode = strtolower((string) $shortcode);

        // The matcher only recognises these characters, so a name carrying
        // anything else could never be typed back. Rejected loudly rather than
        // written into a table where it would sit unreachable.
        if (preg_match('/\A[a-z0-9_+-]+\z/', $shortcode) !== 1) {
            $rejected[] = $shortcode;
            continue;
        }

        // Digit-only names are kept, which is a judged trade rather than an
        // oversight. :100: is one of the most typed shortcodes there is, and
        // GitHub, Slack and Discord all accept it; dropping it to protect
        // against a string like "1:100:1000" would lose something people use
        // constantly to guard against something they almost never write. Times
        // and ratios are safe regardless - a match also has to BE a shortcode,
        // and 12:30:45 contains none.

        // First one wins: the set lists its preferred name first, and a later
        // alias should not displace it.
        $map[$shortcode] ??= $emoji;
    }
}

ksort($map);

if ($map === []) {
    fwrite(STDERR, "The shortcode set produced no usable entries.\n");
    exit(1);
}

$generated_note = 'Generated by bin/generate-emoji-shortcodes.php - do not edit by hand.';

// ---------------------------------------------------------------- PHP

$php_entries = '';

foreach ($map as $shortcode => $emoji) {
    $php_entries .= "        '" . $shortcode . "' => \"" . implode('', array_map(
        static fn (string $byte): string => '\\x' . strtoupper(bin2hex($byte)),
        str_split($emoji)
    )) . "\",\n";
}

$php = <<<PHP
<?php

declare(strict_types=1);

/**
 * {$generated_note}
 *
 * Shortcode to emoji, from emojibase's GitHub set. Read by EmojiShortcode,
 * which does the substituting; this holds nothing but the table.
 *
 * The characters are written as byte escapes rather than literally, so the file
 * is diffable and survives any editor or terminal that would otherwise mangle
 * an emoji it cannot display.
 */
class EmojiShortcodeMap
{
    /** @var array<string, string> */
    public const MAP = [
{$php_entries}    ];
}

PHP;

file_put_contents($project_root . '/src/classes/EmojiShortcodeMap.php', $php);

// ---------------------------------------------------------------- JS

$js_entries = '';

foreach ($map as $shortcode => $emoji) {
    $js_entries .= "    '" . $shortcode . "': '" . implode('', array_map(
        static fn (string $codepoint): string => '\\u{' . dechex(mb_ord($codepoint, 'UTF-8')) . '}',
        mb_str_split($emoji)
    )) . "',\n";
}

$js = <<<JS
// {$generated_note}
//
// Shortcode to emoji, from emojibase's GitHub set. The same table the server
// holds in EmojiShortcodeMap.php, generated from the same source in the same
// run, so the two cannot disagree about what a shortcode means.
//
// Escapes rather than literal characters, for the same reason as the PHP side.

export const EMOJI_SHORTCODES = {
{$js_entries}};

JS;

file_put_contents($project_root . '/scripts/EmojiShortcodeMap.js', $js);

fwrite(STDOUT, 'Wrote ' . count($map) . " shortcodes to both tables.\n");

if ($rejected !== []) {
    fwrite(STDOUT, 'Rejected ' . count($rejected) . ' unusable name(s): ' . implode(', ', array_slice($rejected, 0, 10)) . "\n");
}
